package gallery

const shellDemoHTML = `
{{define "identity-content"}}<dl class="text-sm"><dt class="text-ink-muted">Email</dt><dd class="mt-2 break-all font-medium">alex@example.test</dd><dt class="mt-4 text-ink-muted">Permission</dt><dd class="mt-2 font-medium">{{.State.Access}}</dd></dl>{{end}}
{{define "digest-content"}}{{.Digest}}{{with index .Errors "digest"}}<p id="shell-digest-error" class="mt-2 text-sm text-danger">{{.}}</p>{{end}}{{end}}
{{define "document"}}<!doctype html>
<html lang="en"{{if .Theme}} data-theme="{{.Theme}}"{{end}}{{if .LiveObserver}} data-nonce="{{.Nonce}}"{{end}}><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{{.Title}} · app-kit Gallery shell laboratory</title><script nonce="{{.Nonce}}">{{.Bootstrap}}</script><link rel="stylesheet" href="/static/app.css"><script src="/static/shell-demo.js" defer></script>{{if .LiveObserver}}<script type="module" src="/static/shell-live-entry.js"></script>{{end}}</head><body class="bg-surface-sunken font-sans text-ink">{{.Shell}}
<nav aria-label="Quick navigation" class="fixed inset-x-0 bottom-0 z-20 grid grid-cols-4 border-t border-line bg-surface-raised px-2 pb-[env(safe-area-inset-bottom)] md:hidden">
<a href="/shell"{{if eq .Page "home"}} aria-current="page"{{end}} class="min-w-0 rounded-md px-2 py-4 text-center text-xs font-medium [overflow-wrap:anywhere] {{if eq .Page "home"}}bg-accent-soft text-accent{{else}}text-ink-muted{{end}} focus-visible:outline-2 focus-visible:outline-focus">Overview</a><a href="/shell/activity"{{if eq .Page "activity"}} aria-current="page"{{end}} class="min-w-0 rounded-md px-2 py-4 text-center text-xs font-medium [overflow-wrap:anywhere] {{if eq .Page "activity"}}bg-accent-soft text-accent{{else}}text-ink-muted{{end}} focus-visible:outline-2 focus-visible:outline-focus">Activity</a><a href="/shell/profile"{{if eq .Page "profile"}} aria-current="page"{{end}} class="min-w-0 rounded-md px-2 py-4 text-center text-xs font-medium [overflow-wrap:anywhere] {{if eq .Page "profile"}}bg-accent-soft text-accent{{else}}text-ink-muted{{end}} focus-visible:outline-2 focus-visible:outline-focus">Profile</a><a href="/shell/settings"{{if eq .Page "settings"}} aria-current="page"{{end}} class="min-w-0 rounded-md px-2 py-4 text-center text-xs font-medium [overflow-wrap:anywhere] {{if eq .Page "settings"}}bg-accent-soft text-accent{{else}}text-ink-muted{{end}} focus-visible:outline-2 focus-visible:outline-focus">Settings</a>
</nav></body></html>{{end}}

{{define "hidden"}}<input type="hidden" name="csrf" value="{{.CSRF}}"><input type="hidden" name="return_to" value="{{.Page}}">{{end}}
{{define "actions"}}<details class="relative"><summary class="cursor-pointer rounded-md px-3 py-2 text-sm font-medium focus-visible:outline-2 focus-visible:outline-focus">My account</summary><div class="absolute right-0 z-30 mt-2 w-64 max-w-[calc(100vw-2rem)] rounded-md border border-line bg-surface-raised p-4 shadow-sm">
{{if .State.SignedIn}}<p class="break-words text-sm font-semibold">{{.State.DisplayName}}</p><p class="mt-1 text-xs text-ink-muted">Synthetic account · {{.State.Access}}</p><nav aria-label="Account destinations" class="mt-4">{{.AccountNav}}</nav><form action="/shell/action" method="post" class="mt-4 border-t border-line pt-3">{{template "hidden" .}}<input type="hidden" name="action" value="signout"><button class="text-sm font-medium text-accent underline focus-visible:outline-2 focus-visible:outline-focus">Sign out of demo</button></form>
{{else}}<p class="text-sm text-ink-muted">Signed out of the synthetic account.</p><form action="/shell/action" method="post" class="mt-4">{{template "hidden" .}}<input type="hidden" name="action" value="signin"><button class="text-sm font-medium text-accent underline focus-visible:outline-2 focus-visible:outline-focus">Sign in to demo</button></form>{{end}}
</div></details>{{end}}

{{define "content"}}<div class="mx-auto max-w-4xl pb-24 md:pb-4">
<aside class="mb-8 flex flex-wrap items-baseline justify-between gap-3 border-b border-line pb-4 text-xs text-ink-muted" aria-label="Demonstration boundary"><p>Interactive shell laboratory. Fictional data, local session only.</p><a href="/catalog" class="text-accent underline">Return to catalog</a></aside>
{{.Feedback}}
{{if .Errors}}<ul aria-label="Fields to correct" class="mb-6 space-y-2 text-sm">{{range $field,$error := .Errors}}<li><a href="#shell-{{$field}}" class="text-danger underline">{{$error}}</a></li>{{end}}</ul>{{end}}
{{if and .DraftSummary (not .CanEdit)}}<section class="mb-8 rounded-md border border-line bg-surface-raised p-4"><label for="shell-retained-draft" class="block text-sm font-semibold">Your unsubmitted draft</label><textarea id="shell-retained-draft" readonly rows="4" class="mt-3 w-full rounded-md border border-line bg-surface p-3 font-mono text-xs focus-visible:outline-2 focus-visible:outline-focus">{{.DraftSummary}}</textarea><p class="mt-3 max-w-prose text-sm text-ink-muted">No changes were saved. Copy this draft before signing in or recovering the simulated data source; recovery navigation reloads saved values, not this submission.</p></section>{{end}}
{{if eq .Status 409}}<section class="mb-8 border-y border-line py-5" aria-labelledby="shell-conflict-title"><h2 id="shell-conflict-title" class="font-semibold">Currently saved values</h2><dl class="mt-3 grid gap-3 text-sm sm:grid-cols-2"><div><dt class="text-ink-muted">Display name</dt><dd class="break-words font-medium">{{.State.DisplayName}}</dd></div><div><dt class="text-ink-muted">Preferences</dt><dd class="break-words">{{.State.TimeZone}} · {{.State.StartPage}} · digest {{if .State.Digest}}included{{else}}excluded{{end}}</dd></div></dl><p class="mt-3 max-w-prose text-sm text-ink-muted">Your draft is still below. Compare it with these saved values. Apply reviewed draft replaces them with your edits; another intervening save will require review again.</p></section>{{end}}
{{if eq .Page "home"}}
  <section aria-labelledby="shell-welcome"><p class="text-sm font-medium text-accent">APPLICATION SHELL</p><h2 id="shell-welcome" class="mt-3 text-3xl font-semibold">A place for the everyday work</h2><p class="mt-4 max-w-prose text-ink-muted">Update a profile, save preferences, recover a failed change and find help without losing your place. Every action here changes only a fictional session.</p><a href="{{shellURL .State.StartPage}}" class="mt-6 inline-block rounded-md bg-accent px-4 py-2 font-medium text-accent-ink hover:bg-accent-hover focus-visible:outline-2 focus-visible:outline-focus">Open workspace</a></section>
  <section class="mt-10 border-t border-line pt-6" aria-labelledby="shell-summary"><h2 id="shell-summary" class="text-xl font-semibold">Your saved session</h2><dl class="mt-5 grid gap-x-8 gap-y-5 sm:grid-cols-2"><div><dt class="text-sm text-ink-muted">Display name</dt><dd class="mt-1 break-words font-medium">{{.State.DisplayName}}</dd></div><div><dt class="text-sm text-ink-muted">Time zone</dt><dd class="mt-1 font-medium">{{.State.TimeZone}}</dd></div><div><dt class="text-sm text-ink-muted">Permission</dt><dd class="mt-1 font-medium">{{.State.Access}} · {{if .State.SignedIn}}signed in{{else}}signed out{{end}}</dd></div><div><dt class="text-sm text-ink-muted">Weekly digest</dt><dd class="mt-1 font-medium">{{if .State.Digest}}Included in sample preference{{else}}Excluded from sample preference{{end}}</dd></div></dl><div class="mt-6 flex flex-wrap gap-5 text-sm"><a href="/shell/profile" class="text-accent underline">Edit profile</a><a href="/shell/settings" class="text-accent underline">Change preferences</a><a href="/shell/help" class="text-accent underline">Get help</a></div></section>
{{else if eq .Page "activity"}}
  <section aria-labelledby="shell-activity-title"><h2 id="shell-activity-title" class="text-2xl font-semibold">Session activity</h2><p class="mt-3 max-w-prose text-sm text-ink-muted">The latest ten synthetic changes. This is not a durable audit log and includes no real account activity.</p>
  {{if .LiveObserver}}<section id="shell-live" data-state="idle" aria-labelledby="shell-live-title" class="mt-6 border-t border-line pt-5"><h3 id="shell-live-title" class="font-semibold">Watch this session</h3><p class="mt-2 max-w-prose text-sm text-ink-muted">Optional live observer experiment. Connect here, then save a change in another tab. Ordinary forms stay unchanged. Hiding or leaving this page stops watching; returning never reconnects automatically.</p>
  <form id="shell-live-form" action="/shell/activity" method="get" class="mt-4 flex flex-wrap items-center gap-5"><button id="shell-live-start" type="button" disabled data-on:click="window.AppKitShellLive.connect(() => @get('/shell/events', {contentType: 'form', selector: '#shell-live-form', headers: {Accept: 'text/event-stream'}, openWhenHidden: true, retry: 'never', retryMaxCount: 0, requestCancellation: window.AppKitShellLive.controller}))" class="rounded-md bg-accent px-4 py-2 text-sm font-medium text-accent-ink focus-visible:outline-2 focus-visible:outline-focus disabled:opacity-60">Connect to updates</button><button id="shell-live-stop" type="button" disabled class="text-sm text-accent underline focus-visible:outline-2 focus-visible:outline-focus disabled:opacity-60">Stop watching</button><a href="/shell/activity" class="text-sm text-accent underline">Reload activity</a></form>
  <p id="shell-live-status" role="status" aria-live="polite" class="mt-4 max-w-prose text-sm text-ink-muted">Not watching. Showing the page-load snapshot. Connect or reload to check for changes.</p><noscript><p class="mt-3 text-sm text-ink-muted">Live updates require scripts. Reload activity to get a new ordinary page; saving works without scripts.</p></noscript>
  <div id="shell-live-content"><p id="shell-live-summary" class="mt-5 break-words text-sm text-ink-muted">Page-load version {{.State.Version}} · {{.State.DisplayName}} · {{.State.Access}} · account {{.State.Availability}}</p><ol id="shell-live-activity" class="mt-3 divide-y divide-line border-y border-line">{{range .State.Activity}}<li class="py-4 text-sm">{{.}}</li>{{end}}</ol></div></section>
  {{else}}<ol class="mt-6 divide-y divide-line border-y border-line">{{range .State.Activity}}<li class="py-4 text-sm">{{.}}</li>{{end}}</ol>{{end}}<a href="/shell/profile" class="mt-5 inline-block text-sm text-accent underline">Return to profile</a></section>
{{else if or (eq .Page "profile") (eq .Page "settings")}}
  {{if not .State.SignedIn}}<section aria-labelledby="shell-signin-title"><h2 id="shell-signin-title" class="text-2xl font-semibold">Sign in to continue</h2><p class="mt-3 max-w-prose text-sm text-ink-muted">This is a simulated signed-out state. No identity provider, password or real account is involved.</p><form action="/shell/action" method="post" class="mt-6">{{template "hidden" .}}<input type="hidden" name="action" value="signin"><button class="rounded-md bg-accent px-4 py-2 font-medium text-accent-ink focus-visible:outline-2 focus-visible:outline-focus">Sign in to demo</button></form></section>
  {{else if ne .State.Availability "ready"}}<section aria-labelledby="shell-unavailable-title"{{if eq .State.Availability "loading"}} aria-busy="true"{{end}}><h2 id="shell-unavailable-title" class="text-2xl font-semibold">{{if eq .State.Availability "loading"}}Loading-state fixture{{else}}The sample account could not be loaded{{end}}</h2><p class="mt-3 max-w-prose text-sm text-ink-muted">{{if eq .State.Availability "loading"}}This is a paused loading specimen, not a live request. Finish the simulated load to continue.{{else}}Saved values remain unchanged. Retry the simulated load to recover the page.{{end}}</p>{{if eq .State.Availability "loading"}}<div aria-hidden="true" class="mt-6 space-y-4"><div class="h-4 w-40 rounded bg-line"></div><div class="h-11 max-w-md rounded bg-surface-raised"></div><div class="h-4 w-56 rounded bg-line"></div></div>{{end}}<form action="/shell/action" method="post" class="mt-6">{{template "hidden" .}}<input type="hidden" name="action" value="retry-load"><button class="rounded-md bg-accent px-4 py-2 font-medium text-accent-ink focus-visible:outline-2 focus-visible:outline-focus">{{if eq .State.Availability "loading"}}Finish simulated load{{else}}Retry loading account{{end}}</button></form></section>
  {{else}}
    <div class="max-w-prose"><h2 class="text-2xl font-semibold">{{if eq .Page "profile"}}Your profile{{else}}Your preferences{{end}}</h2><p class="mt-3 text-sm text-ink-muted">{{if eq .Page "profile"}}Choose how your name appears in this sample workspace. Identity and permission remain owned by the host application.{{else}}Make the workspace fit your routine. Account preferences save on this local demo server; appearance is a separate browser preference.{{end}}</p></div>
    {{if not .CanEdit}}<p role="status" class="mt-5 rounded-md border border-line bg-surface-raised p-4 text-sm">Read-only access. Your host application decides who may edit. The server refuses saves in this fixture even if disabled controls are changed.</p>{{end}}
    <form action="/shell/action" method="post" autocomplete="off"{{if .CanEdit}} data-shell-edit data-shell-baseline="{{.Baseline}}"{{if ge .Status 400}} data-shell-retry="true"{{end}}{{end}} class="mt-8">{{template "hidden" .}}<input type="hidden" name="action" value="{{.Action}}"><input type="hidden" name="version" value="{{.State.Version}}">
      {{.FormSections}}
      {{if .CanEdit}}<div class="mt-6 flex flex-wrap items-center justify-between gap-4"><p data-shell-draft-status role="status" aria-live="polite" class="text-sm text-ink-muted">Changes save when you submit this form.</p><div class="flex flex-wrap items-center gap-5"><a href="{{.CurrentURL}}" class="text-sm text-accent underline">Discard draft and reload</a><button data-shell-resume type="button" hidden class="text-sm text-accent underline focus-visible:outline-2 focus-visible:outline-focus">Resume editing after interrupted save</button><button data-shell-save class="rounded-md bg-accent px-4 py-2 text-sm font-medium text-accent-ink hover:bg-accent-hover focus-visible:outline-2 focus-visible:outline-focus disabled:opacity-60">{{.SubmitLabel}}</button></div></div><noscript><p class="mt-4 text-sm text-ink-muted">Saving and validation work without scripts. Unsaved-change warnings and inline save progress require scripts.</p></noscript>{{end}}
    </form>
    {{if eq .Page "settings"}}<section class="mt-10 grid gap-x-8 gap-y-6 border-t border-line pt-7 sm:grid-cols-2" aria-labelledby="shell-appearance-title"><div><h3 id="shell-appearance-title" class="font-semibold">Appearance</h3><p class="mt-2 text-sm text-ink-muted">Follows the device unless you choose light or dark. Applies immediately; storage failure keeps the current page usable and offers retry.</p></div><div>{{.Appearance}}</div></section>{{end}}
  {{end}}
{{else if eq .Page "help"}}
  <section aria-labelledby="shell-help-title"><h2 id="shell-help-title" class="text-2xl font-semibold">Help with this workspace</h2><p class="mt-3 max-w-prose text-sm text-ink-muted">Start with the task that is blocked. These recovery paths work without a support service.</p><div class="mt-7 divide-y divide-line border-y border-line"><details class="py-5"><summary class="cursor-pointer font-medium">A profile or preference will not save</summary><p class="mt-3 max-w-prose text-sm text-ink-muted">Correct linked field errors, then save again. A temporary failure keeps your draft visible. A conflicting save shows the latest saved values before you apply a reviewed draft. Read-only access must be changed by the host's authorization policy.</p><a href="/shell/profile" class="mt-3 inline-block text-sm text-accent underline">Return to profile</a></details><details class="py-5"><summary class="cursor-pointer font-medium">Use the workspace with a keyboard</summary><p class="mt-3 max-w-prose text-sm text-ink-muted">Use the first skip link to reach content. Tab and Shift+Tab move through controls; Enter or Space opens native disclosures. Menus use ordinary links, not a custom arrow-key menu. Browser Back returns to the previous page.</p></details><details class="py-5"><summary class="cursor-pointer font-medium">Appearance changed but was not saved</summary><p class="mt-3 max-w-prose text-sm text-ink-muted">The appearance control reports whether storage succeeded. Use its retry button or continue with the page's current appearance. System removes the saved override. No account preference is changed by this control.</p><a href="/shell/settings" class="mt-3 inline-block text-sm text-accent underline">Open appearance settings</a></details><details class="py-5"><summary class="cursor-pointer font-medium">Report a problem without exposing account data</summary><p class="mt-3 max-w-prose text-sm text-ink-muted">Copy the allowlisted build information from About. Add the action and observed result yourself. Do not include cookies, form tokens or private data. This demo neither uploads diagnostics nor opens an external support destination.</p><a href="/shell/about" class="mt-3 inline-block text-sm text-accent underline">View safe build information</a></details></div></section>
{{else if eq .Page "about"}}
  <section aria-labelledby="shell-about-title"><h2 id="shell-about-title" class="text-2xl font-semibold">About this laboratory</h2><p class="mt-3 max-w-prose text-sm text-ink-muted">A composed reference using the kit's dashboard shell, typed navigation, form controls and appearance controller. It is not an identity provider or production persistence layer.</p><label for="shell-diagnostics" class="mt-7 block text-sm font-medium">Safe diagnostic summary</label><textarea id="shell-diagnostics" readonly rows="7" class="mt-3 w-full rounded-md border border-line bg-surface-raised p-4 font-mono text-xs focus-visible:outline-2 focus-visible:outline-focus">{{.Diagnostics}}</textarea><p class="mt-2 max-w-prose text-xs text-ink-muted">Select and copy with your normal keyboard or pointer controls. No username, session token, local path, environment dump or automatic upload is included.</p><a href="/shell/help" class="mt-6 inline-block text-sm text-accent underline">Return to help</a></section>
{{end}}
{{template "fixtures" .}}
</div>{{end}}

{{define "fixtures"}}<details class="mt-12 border-t border-line pt-6"><summary class="cursor-pointer text-sm font-medium text-ink-muted">Laboratory controls and evidence limits</summary><p class="mt-4 max-w-prose text-sm text-ink-muted">Use fictional permission and failure states to exercise recovery. These controls are not real authorization. Sessions expire 30 minutes after creation and disappear when this process stops.</p><form action="/shell/action" method="post" class="mt-5 grid gap-4 sm:grid-cols-2">{{template "hidden" .}}<input type="hidden" name="action" value="fixture"><div><label for="shell-access" class="block text-sm font-medium">Permission fixture</label><select id="shell-access" name="access" class="mt-2 w-full rounded-md border border-line bg-surface p-2 text-sm"><option value="editor"{{if eq .State.Access "editor"}} selected{{end}}>Editor</option><option value="viewer"{{if eq .State.Access "viewer"}} selected{{end}}>Read-only viewer</option></select></div><div><label for="shell-availability" class="block text-sm font-medium">Account load fixture</label><select id="shell-availability" name="availability" class="mt-2 w-full rounded-md border border-line bg-surface p-2 text-sm"><option value="ready"{{if eq .State.Availability "ready"}} selected{{end}}>Ready</option><option value="loading"{{if eq .State.Availability "loading"}} selected{{end}}>Paused loading specimen</option><option value="error"{{if eq .State.Availability "error"}} selected{{end}}>Load failure</option></select></div><label class="flex items-center gap-3 text-sm"><input type="checkbox" name="fail_next_save" value="on"{{if .State.FailNextSave}} checked{{end}}>Fail the next valid save once</label><button class="justify-self-start rounded-md border border-line bg-surface px-4 py-2 text-sm font-medium focus-visible:outline-2 focus-visible:outline-focus">Apply fixture</button></form><form action="/shell/action" method="post" class="mt-5">{{template "hidden" .}}<input type="hidden" name="action" value="reset-demo"><button class="text-sm text-accent underline focus-visible:outline-2 focus-visible:outline-focus">Reset my synthetic session</button></form><p class="mt-5 max-w-prose text-xs text-ink-muted">HTTP and state tests do not certify keyboard behavior, contrast, visual quality, performance or desktop support. Consumer apps still own their real routes, identity, authorization, settings schema and persistence.</p></details>{{end}}
`
